//预处理程序
bool preProcess(const string fileName, const string newFileName) {
	//打开原始文件
	ifstream inFile(fileName);
	if (!inFile) {
		cout << "源文件打开失败！" << endl;
		return false;
	}
	//将源程序读入缓冲区
	stringstream buffer;
	buffer << inFile.rdbuf();
	string text = buffer.str();
	inFile.close();

	//去除注释（支持 // 单行注释与 /* */ 多行注释）
	string noComment;
	for (int i = 0; i < (int)text.length(); i++) {
		if (text[i] == '/' && i + 1 < (int)text.length() && text[i + 1] == '/') {
			while (i < (int)text.length() && text[i] != '\n') i++;
		}
		else if (text[i] == '/' && i + 1 < (int)text.length() && text[i + 1] == '*') {
			i += 2;
			while (i + 1 < (int)text.length() && !(text[i] == '*' && text[i + 1] == '/')) i++;
			i++;
		}
		else {
			noComment += text[i];
		}
	}

	//去除换行符、制表符，并将连续空格压缩为一个空格
	string normalized;
	bool lastSpace = true;   // 避免开头出现空格
	for (int i = 0; i < (int)noComment.length(); i++) {
		char c = noComment[i];
		if (c == '\n' || c == '\r' || c == '\t') continue;
		if (c == ' ') {
			if (lastSpace) continue;
			lastSpace = true;
			normalized += c;
		}
		else {
			lastSpace = false;
			normalized += c;
		}
	}
	//去掉末尾空格
	while (!normalized.empty() && normalized.back() == ' ') normalized.pop_back();
```

