```cpp
void split_into_rules(const string text, vector<rule> &rules, set<char> &non_terminal, set<char> &terminal, set<string> &right_parts) {
	//按空白切分出每条规则
	vector<string> rule_strs;
	string cur = "";
	for (char c : text) {
		if (c == ' ' || c == '\t' || c == '\n' || c == '\r') {
			if (!cur.empty()) { rule_strs.push_back(cur); cur = ""; }
		}
		else cur += c;
	}
	if (!cur.empty()) rule_strs.push_back(cur);

	//解析 ::= 与 |
	for (string s : rule_strs) {
		size_t pos = s.find("::=");
		if (pos == string::npos || pos == 0) continue;
		rule r;
		r.left = s[0];
		string body = s.substr(pos + 3);
		string part = "";
		for (char c : body) {
			if (c == '|') { r.right.push_back(part); part = ""; }
			else part += c;
		}
		r.right.push_back(part);
		rules.push_back(r);
		non_terminal.insert(r.left);
		for (string rp : r.right) right_parts.insert(rp);
	}
	//提取终结符：右部中不是非终结符且不是空串符号'@'的字符
	for (rule r : rules) {
		for (string rp : r.right) {
			for (char c : rp) {
				if (c == '@') continue;
				if (non_terminal.count(c)) continue;
				terminal.insert(c);
			}
		}
	}
}
```

