findFollow:
```cpp
F_set findFollow(const char non_terminal, vector<rule> rules) {
	F_set f_set;
	f_set.is_first = false;
	f_set.left = string(1, non_terminal);
	f_set.right.insert('#');
	for (rule r : rules) {
		for (string rp : r.right) {
			for (int i = 0; i < (int)rp.length(); i++) {
				if (rp[i] != non_terminal) continue;
				if (i + 1 < (int)rp.length()) {
					F_set sub = findFirst(rp.substr(i + 1), rules);
					for (char c : sub.right)
						if (c != '@') f_set.right.insert(c);
					if (sub.right.count('@') && r.left != non_terminal) {
						F_set parent = findFollow(r.left, rules);
						f_set.right.insert(parent.right.begin(), parent.right.end());
					}
				}
				else if (r.left != non_terminal) {
					F_set parent = findFollow(r.left, rules);
					f_set.right.insert(parent.right.begin(), parent.right.end());
				}
			}
		}
	}
	return f_set;
}
```

