```cpp
void syntacticAnalysis(LL_1_table table) {
	cout << endl << "接下来进行语法分析" << endl << "请输入字符串：" << endl;
	string input;
	cin >> input;

	//初始化分析栈与输入栈
	stack<char> analysis_s;
	stack<char> input_s;
	analysis_s.push('#');
	analysis_s.push(table.row[0]);   //开始符号
	input_s.push('#');
	for (int i = (int)input.length() - 1; i >= 0; i--) input_s.push(input[i]);

	//输出表头
	cout << setw(16) << "分析栈" << setw(16) << "剩余输入串" << "  " << "所用产生式" << endl;

	bool accept = true;
	rule rule_temp;
	int cols = table.col.size();
	while (true) {
		char top = analysis_s.top();
		char cur = input_s.top();
		if (top == '#' && cur == '#') break;    //分析成功
		bool top_terminal = (top == '#') || (find(table.col.begin(), table.col.end(), top) != table.col.end());
		if (top_terminal) {
			if (top != cur) { accept = false; break; }
			rule_temp = rule();
			print_state(analysis_s, input_s, rule_temp);
			analysis_s.pop();
			input_s.pop();
		}
		else {
			int ri = -1, ci = -1;
			for (int i = 0; i < (int)table.row.size(); i++) if (table.row[i] == top) ri = i;
			for (int j = 0; j < cols; j++) if (table.col[j] == cur) ci = j;
			if (ri == -1 || ci == -1 || table.rules[ri * cols + ci].right.empty()) {
				accept = false;
				break;
			}
			rule_temp = table.rules[ri * cols + ci];
			print_state(analysis_s, input_s, rule_temp);
			analysis_s.pop();
			string rp = rule_temp.right[0];
			if (rp != "@")
				for (int i = (int)rp.length() - 1; i >= 0; i--) analysis_s.push(rp[i]);
		}
	}

	cout << endl << "字符串" << input;
	if (!accept) cout << "不";
	cout << "是该文法的句子" << endl;
}
